    $('names').disabled=busy||locked();$('manual').disabled=busy||locked();$('itemclear').disabled=busy||locked();
    const ready=!parsed.error && all.length>=2 && all.length<=MAX && parsed.total<=MAX_TICKETS;
    const canSpin=!busy && (state.mode==='elimination'?(r.active?!r.finished&&uniqueNames(r.remaining).length>=2:ready):ready);
    $('spin').disabled=!canSpin;$('hub').disabled=!canSpin;$('present-spin').disabled=!canSpin;$('reset').disabled=busy;
    $('compact-info').textContent=state.winner ? '🏆 '+state.winner.winner+' · '+(state.item.name||'Wynik losowania') : list.length ? uniqueNames(list).length+' osób · '+list.length+' losów · '+(state.mode==='elimination'?'Eliminacje':state.mode==='race'?'Wyścig':'Jedno losowanie') : 'Brak uczestników — dodaj ich w pełnym panelu';
    $('shuffle').disabled=busy || (locked()?r.finished||r.remaining.length<2:parsed.total<2 || !!parsed.error);
    $('spin').textContent=state.mode==='race'?'🏇 ROZPOCZNIJ WYŚCIG':state.mode==='single'?'✦ ZAKRĘĆ KOŁEM':r.finished?'🏆 RUNDA ZAKOŃCZONA':r.active?'☠ ELIMINUJ KOLEJNĄ OSOBĘ':'☠ ROZPOCZNIJ ELIMINACJE';

    const duel=state.mode==='elimination' && uniqueNames(list).length===2 && !r.finished;
    $('wheelwrap').classList.toggle('duel',duel);
